import{_ as a,o,c as t,a5 as d}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse(`{"title":"zip方法","description":"这段代码的目的是创建一个映射关系，将标准的字母表映射到根据密钥生成的新字母表，同时处理小写和大写字母。这里详细解释一下这段代码： 字母表和新字母表 alphabet 是一个字符串，包含了标准的小写字母表（'abcdefghijklmnopqrstuvwxyz'）。 new alp。","frontmatter":{"title":"zip方法","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"这段代码的目的是创建一个映射关系，将标准的字母表映射到根据密钥生成的新字母表，同时处理小写和大写字母。这里详细解释一下这段代码： 字母表和新字母表 alphabet 是一个字符串，包含了标准的小写字母表（'abcdefghijklmnopqrstuvwxyz'）。 new alp。","sidebarWeight":7,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/HJ36 字符串加密/zip方法.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/HJ36 字符串加密/zip方法.md","filePath":"posts/前端面试与实战/03-算法训练/HJ36 字符串加密/zip方法.md"}`),i={name:"posts/前端面试与实战/03-算法训练/HJ36 字符串加密/zip方法.md"};function c(l,e,p,r,n,s){return o(),t("div",null,[...e[0]||(e[0]=[d('<div><h1 id="zip方法" tabindex="-1">zip方法 <a class="header-anchor" href="#zip方法" aria-label="Permalink to &quot;zip方法&quot;">​</a></h1><blockquote><p>本节目标：理解“zip方法”的核心思路，并能把它用于实际开发或面试表达。 这段代码的目的是创建一个映射关系，将标准的字母表映射到根据密钥生成的新字母表，同时处理小写和大写字母。这里详细解释一下这段代码：</p></blockquote><h3 id="字母表和新字母表" tabindex="-1">字母表和新字母表 <a class="header-anchor" href="#字母表和新字母表" aria-label="Permalink to &quot;字母表和新字母表&quot;">​</a></h3><ul><li><code>alphabet</code> 是一个字符串，包含了标准的小写字母表（&#39;abcdefghijklmnopqrstuvwxyz&#39;）。</li><li><code>new_alphabet</code> 是根据输入密钥生成的新字母表的列表，首先包含密钥中的所有不重复字母（保持顺序），然后包含字母表中未出现在密钥中的剩余字母。</li></ul><h3 id="映射关系的建立" tabindex="-1">映射关系的建立 <a class="header-anchor" href="#映射关系的建立" aria-label="Permalink to &quot;映射关系的建立&quot;">​</a></h3><ul><li><p><code>zip(alphabet, new_alphabet)</code> 这个函数将两个序列（<code>alphabet</code> 和 <code>new_alphabet</code>）&quot;压缩&quot;成一个迭代器，迭代器中的元素是元组，每个元组包含来自两个序列的对应元素。例如，如果 <code>alphabet</code> 是 <code>&#39;abc&#39;</code>，而 <code>new_alphabet</code> 是 <code>&#39;xyz&#39;</code>，<code>zip</code> 函数会产生一个迭代器，其中包含元组 <code>(&#39;a&#39;, &#39;x&#39;)</code>、<code>(&#39;b&#39;, &#39;y&#39;)</code> 和 <code>(&#39;c&#39;, &#39;z&#39;)</code>。</p></li><li><p><code>for original, new in zip(alphabet, new_alphabet):</code> 这行代码遍历 <code>zip</code> 函数产生的迭代器。在每次迭代中，<code>original</code> 是来自标准字母表的字母，而 <code>new</code> 是来自新字母表的对应字母。这个循环逐一处理字母表中的每个字母，将它们从原始字母映射到新字母。</p></li></ul><h3 id="映射字典的填充" tabindex="-1">映射字典的填充 <a class="header-anchor" href="#映射字典的填充" aria-label="Permalink to &quot;映射字典的填充&quot;">​</a></h3><ul><li><p>在循环体内部，代码首先为小写字母创建映射关系：<code>letter_mapping[original] = new</code>。这意味着，在加密过程中，任何出现的 <code>original</code> 字母都将被替换为 <code>new</code> 字母。</p></li><li><p>接着，为了处理大写字母，代码使用了 <code>letter_mapping[original.upper()] = new.upper()</code>。这行代码的作用是，将 <code>original</code> 字母转换为大写，找到其对应的大写形式的 <code>new</code> 字母（也转换为大写），并建立映射关系。这确保了无论原文中的字母是大写还是小写，都可以正确地映射到新的字母表中对应的字母，同时保留原有的大小写状态。</p></li></ul><h3 id="结果" tabindex="-1">结果 <a class="header-anchor" href="#结果" aria-label="Permalink to &quot;结果&quot;">​</a></h3><p>通过这种方式，<code>letter_mapping</code> 字典存储了从标准字母表到新字母表的完整映射关系，包括小写和大写字母。这使得后续的加密过程可以直接通过查找字典来进行，大大提高了效率，并保持了文本的大小写格式。</p></div>',1)])])}const _=a(i,[["render",c]]);export{u as __pageData,_ as default};
